#!/usr/bin/env bash
set -euo pipefail

# ConvertLAB Upgrade — apply patch
# Foundation + calculators/conversions/lab-tools/spectrophotometry, PWA offline
# support, accessibility fixes (incl. WCAG AA contrast pass), unit test suite,
# blue theming, back button, maintenance banner, an RSC server/client boundary
# bug fix, additional calculators, a lazy-loaded chart dependency, a local
# Dashboard Statistics widget, an Inputs recap section, Export PDF, missing
# lab-prep/calculation disclaimers, full unit selection on Mass<->Volume,
# Hematology/Clinical Chemistry reference range tables, a dashboard pass
# (greeting, Popular Tools, Browse row), global search now covering every
# standalone lab tool (previously unsearchable), and a combined Red Cell
# Indices tool (enter Hgb/Hct/RBC once, get MCV/MCH/MCHC together).
#
# This project uses pnpm. Run this from the ROOT of your ConvertLAB repo
# (the directory containing package.json, app/, components/, lib/).

if [ ! -f "package.json" ]; then
  echo "Error: run this script from the root of your ConvertLAB repo (package.json not found here)."
  exit 1
fi

echo "Removing superseded files (now replaced by the new calculator/conversion engine, or a stray npm lockfile)..."
rm -f -- "components/calculators/blood-calculator.tsx"
rm -f -- "components/calculators/bmi-calculator.tsx"
rm -f -- "components/calculators/lab-converter.tsx"
rm -f -- "components/calculators/ldl-calculator.tsx"
rm -f -- "components/calculators/temperature-converter.tsx"
rm -f -- "components/calculators/unit-converter.tsx"
rm -f -- "components/navigation.tsx"
rm -f -- "package-lock.json"

echo "Writing 96 new and updated files..."

